/**
 * Human-readable PMS record codes, e.g. `DMD-000123`.
 *
 * Codes are generated by the API from an atomic counter per prefix. They are unique,
 * immutable and never reused; gaps are possible (a code reserved for a write that then
 * failed is not handed out again). The MongoDB `_id` remains the primary identity.
 */
export const CODE_PREFIX_PATTERN = /^[A-Z][A-Z0-9]{1,7}$/;
export const CODE_DIGITS = 6;
export const RECORD_CODE_PATTERN = /^[A-Z][A-Z0-9]{1,7}-\d{6,}$/;

export function formatRecordCode(prefix: string, sequence: number): string {
  if (!CODE_PREFIX_PATTERN.test(prefix)) {
    throw new Error(`Invalid record code prefix "${prefix}"`);
  }
  if (!Number.isSafeInteger(sequence) || sequence < 1) {
    throw new Error('Record code sequence must be a positive integer');
  }
  return `${prefix}-${String(sequence).padStart(CODE_DIGITS, '0')}`;
}

export function isRecordCode(value: string): boolean {
  return RECORD_CODE_PATTERN.test(value);
}
